def cases_for(field):
    for sample in HOLDOUT:
        yield (sample["id"], sample["text"], sample["ocr_used"],
               sample["expected"].get(field), [])


def reference_cases():
    for sample in HOLDOUT:
        yield (sample["id"], sample["text"], sample["ocr_used"],
               sample["expected"].get("references", []))
